+func mapKeysSorted(v interface{}) []string {
+	m, ok := v.(map[string]interface{})
+	if !ok { return nil }
+	keys := make([]string, 0, len(m))
+	for k := range m { keys = append(keys, k) }
+	sort.Strings(keys)
+	return keys
+}

